        """.trimIndent().lines()
        rows.forEachIndexed { index,row ->
            val columns=row.split('|');val runs=columns.first()
            val binary=runs.split(',').joinToString("") { run -> run.last().toString().repeat(run.dropLast(1).toInt()) }
            for((radixIndex,radix) in listOf(2,8,16).withIndex()) {
                val width=when(radix) { 2 -> 1;8 -> 3;else -> 4 }
                val padded=binary.padStart(((binary.length+width-1)/width)*width,'0')
                val digits=padded.chunked(width).joinToString("") { it.toInt(2).toString(radix) }
                val expected=columns[radixIndex+1].toULong(16).toLong()
                assertEquals(expected,jsNumberFromRadix(digits,radix).toBits(),"Radix case $index/$radix")
                assertEquals(expected,jsNumberFromRadix("0".repeat(10_000)+digits.uppercase(),radix).toBits(),"Leading zeros case $index/$radix")
            }
        }
