    @Test
    fun syntaxIsAsciiAndInvalidOverflowStillReturnsNaN() {
        for((radix,invalid) in listOf(2 to "2",8 to "8",16 to "g")) {
            for(input in listOf("",invalid,"-1","+1"," 1","1 ","١","０","1".repeat(2000)+invalid)) assertTrue(jsNumberFromRadix(input,radix).isNaN())
        }
        assertEquals(0L,jsNumberFromRadix("0".repeat(10_000),16).toBits())
    }
